CREATE TABLE level_event_outbox(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,level INT NOT NULL,occurred_at DATETIME(6) NOT NULL,sent TINYINT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_event(event_id),INDEX idx_pending(sent,id));
